"use client";

import * as React from "react";
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { XIcon } from "lucide-react";
import { ModalPortalScope, useRootPortalContainer } from "@/components/ui/portal";
import { useMergedRefs } from "@/lib/compose-refs";
import { scrollSafeInitialFocus } from "@/lib/initial-focus";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";

const Dialog = DialogPrimitive.Root;

function DialogPortal({ container: containerProp, ...props }: DialogPrimitive.Portal.Props) {
  const rootContainer = useRootPortalContainer();
  const container = containerProp === undefined ? (rootContainer ?? undefined) : containerProp;

  const style = {
    ...(props.style ?? {}),
    // Ensure floating overlays inside dialogs (select/menu/popover/tooltip) stack above the dialog.
    // Nested Base UI portals inherit this var via Base UI portal nesting.
    ['--z-layer-floating' as any]: 'var(--z-layer-floating-elevated)',
  } satisfies React.CSSProperties;

  return <DialogPrimitive.Portal container={container} {...props} style={style} />;
}

type DialogTriggerProps = React.ComponentProps<typeof DialogPrimitive.Trigger> & {
  /** When true, merges props onto the child element instead of rendering a button */
  asChild?: boolean;
};

function DialogTrigger({ asChild, children, render, nativeButton, ...props }: DialogTriggerProps) {
  const childRender = render === undefined && asChild && React.isValidElement(children) ? children : undefined;

  return (
    <DialogPrimitive.Trigger
      data-slot="dialog-trigger"
      nativeButton={nativeButton ?? (childRender ? true : undefined)}
      render={render ?? childRender}
      {...props}
    >
      {childRender ? undefined : children}
    </DialogPrimitive.Trigger>
  );
}

type DialogCloseProps = React.ComponentProps<typeof DialogPrimitive.Close> & {
  /** When true, merges props onto the child element instead of rendering a button */
  asChild?: boolean;
};

function DialogClose({ asChild, children, render, nativeButton, ...props }: DialogCloseProps) {
  const childRender = render === undefined && asChild && React.isValidElement(children) ? children : undefined;

  return (
    <DialogPrimitive.Close
      data-slot="dialog-close"
      nativeButton={nativeButton ?? (childRender ? true : undefined)}
      render={render ?? childRender}
      {...props}
    >
      {childRender ? undefined : children}
    </DialogPrimitive.Close>
  );
}

function DialogBackdrop({
  className,
  ...props
}: DialogPrimitive.Backdrop.Props) {
  return (
    <DialogPrimitive.Backdrop
      className={cn(
        "fixed inset-0 z-[var(--z-layer-modal-backdrop)] bg-black/32 backdrop-blur-sm transition-opacity duration-(--duration-slow) data-ending-style:opacity-0 data-starting-style:opacity-0",
        className,
      )}
      data-slot="dialog-backdrop"
      {...props}
    />
  );
}

function DialogViewport({
  className,
  ...props
}: DialogPrimitive.Viewport.Props) {
  return (
    <DialogPrimitive.Viewport
      className={cn(
        "fixed inset-0 z-[var(--z-layer-modal-content)] grid grid-rows-[1fr_auto_3fr] justify-items-center p-4",
        className,
      )}
      data-slot="dialog-viewport"
      {...props}
    />
  );
}

function DialogPopup({
  className,
  children,
  showCloseButton = true,
  bottomStickOnMobile = true,
  initialFocus,
  ...props
}: DialogPrimitive.Popup.Props & {
  showCloseButton?: boolean;
  bottomStickOnMobile?: boolean;
}) {
  const popupRef = React.useRef<HTMLDivElement>(null);
  const ref = useMergedRefs(popupRef, props.ref);
  return (
    <DialogPortal>
      <DialogBackdrop />
      <DialogViewport
        className={cn(
          bottomStickOnMobile && "max-sm:grid-rows-[1fr_auto] max-sm:pt-12",
        )}
      >
        <DialogPrimitive.Popup
          className={cn(
            "-translate-y-[calc(1.25rem*var(--nested-dialogs))] relative row-start-2 flex max-h-full min-h-0 w-full min-w-0 max-w-lg scale-[calc(1-0.1*var(--nested-dialogs))] flex-col overflow-y-auto overscroll-contain rounded-xl border bg-popover outline-hidden [overflow-wrap:break-word] bg-clip-padding text-popover-foreground opacity-[calc(1-0.1*var(--nested-dialogs))] shadow-lg transition-[scale,opacity,translate] duration-(--duration-slow) ease-in-out before:pointer-events-none before:absolute before:inset-0 before:rounded-[calc(var(--radius-xl)-1px)] before:shadow-[0_1px_--theme(--color-black/4%)] data-nested:data-ending-style:translate-y-8 data-nested:data-starting-style:translate-y-8 data-nested-dialog-open:origin-top data-ending-style:scale-98 data-starting-style:scale-98 data-ending-style:opacity-0 data-starting-style:opacity-0 dark:bg-clip-border dark:before:shadow-[0_-1px_--theme(--color-white/8%)]",
            bottomStickOnMobile &&
              "max-sm:rounded-none max-sm:border-x-0 max-sm:border-t max-sm:border-b-0 max-sm:opacity-[calc(1-min(var(--nested-dialogs),1))] max-sm:data-ending-style:translate-y-4 max-sm:data-starting-style:translate-y-4 max-sm:before:hidden max-sm:before:rounded-none",
            className,
          )}
          data-slot="dialog-popup"
          // A popup that scrolls opens at its top, not scrolled to a footer button that happens to be first in tab order.
          // Leaving `initialFocus` out and passing `undefined` are the same thing: both get this default.
          initialFocus={initialFocus ?? scrollSafeInitialFocus(() => popupRef.current)}
          {...props}
          ref={ref}
        >
          {/* ModalPortalScope creates a scoped portal container for floating elements inside */}
          <ModalPortalScope>
            {children}
          </ModalPortalScope>
          {showCloseButton && (
            <DialogPrimitive.Close
              aria-label="Close"
              nativeButton={true}
              render={(closeProps) => {
                const { nativeButton: _, ...rest } = closeProps as Record<string, unknown>;
                return (
                  <Button
                    {...rest}
                    className="absolute end-2 top-2"
                    size="icon"
                    variant="ghost"
                  >
                    <XIcon />
                  </Button>
                );
              }}
            />
          )}
        </DialogPrimitive.Popup>
      </DialogViewport>
    </DialogPortal>
  );
}

function DialogHeader({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & {
  /** `band` tints the header and closes it with a hairline, mirroring the default footer. */
  variant?: "default" | "band";
}) {
  return (
    <div
      className={cn(
        "flex flex-col gap-2",
        variant === "default" &&
          "p-6 in-[[data-slot=dialog-popup]:has([data-slot=dialog-panel])]:pb-3 max-sm:pb-4",
        // The band carries its own gap below, so a panel or plain body after it needs no top padding.
        variant === "band" &&
          "mb-5 border-b bg-muted/50 px-6 py-4 sm:rounded-t-[calc(var(--radius-xl)-1px)]",
        className,
      )}
      data-slot="dialog-header"
      data-variant={variant}
      {...props}
    />
  );
}

function DialogFooter({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & {
  variant?: "default" | "bare";
}) {
  return (
    <div
      className={cn(
        "flex flex-col-reverse gap-2 px-6 sm:flex-row sm:flex-wrap sm:justify-end sm:rounded-b-[calc(var(--radius-xl)-1px)]",
        variant === "default" && "border-t bg-muted/50 py-4",
        variant === "bare" &&
          "in-[[data-slot=dialog-popup]:has([data-slot=dialog-panel])]:pt-3 pt-4 pb-6",
        className,
      )}
      data-slot="dialog-footer"
      {...props}
    />
  );
}

function DialogTitle({ className, ...props }: DialogPrimitive.Title.Props) {
  return (
    <DialogPrimitive.Title
      className={cn("font-heading text-xl leading-tight pe-6", className)}
      data-slot="dialog-title"
      {...props}
    />
  );
}

function DialogDescription({
  className,
  ...props
}: DialogPrimitive.Description.Props) {
  return (
    <DialogPrimitive.Description
      className={cn("text-muted-foreground text-sm", className)}
      data-slot="dialog-description"
      {...props}
    />
  );
}

function DialogPanel({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <ScrollArea className="min-h-24">
      <div
        className={cn(
          "px-6 in-[[data-slot=dialog-popup]:has([data-slot=dialog-header])]:pt-1 in-[[data-slot=dialog-popup]:not(:has([data-slot=dialog-header]))]:pt-6 in-[[data-slot=dialog-popup]:not(:has([data-slot=dialog-footer]))]:pb-6! in-[[data-slot=dialog-popup]:not(:has([data-slot=dialog-footer].border-t))]:pb-1 pb-6",
          className,
        )}
        data-slot="dialog-panel"
        {...props}
      />
    </ScrollArea>
  );
}

export {
  Dialog,
  DialogTrigger,
  DialogPortal,
  DialogClose,
  DialogBackdrop,
  DialogBackdrop as DialogOverlay,
  DialogPopup,
  DialogPopup as DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
  DialogPanel,
  DialogViewport,
};
